def trap_brute(h):
    n=len(h); ans=0
    for i in range(n):
        lm = max(h[:i+1]); rm=max(h[i:])
        ans += max(0, min(lm,rm)-h[i])
    return ans

def trap_pref(h):
    n=len(h)
    if not n: return 0
    L=[0]*n; R=[0]*n
    L[0]=h[0]
    for i in range(1,n): L[i]=max(L[i-1], h[i])
    R[-1]=h[-1]
    for i in range(n-2,-1,-1): R[i]=max(R[i+1], h[i])
    return sum(max(0, min(L[i],R[i])-h[i]) for i in range(n))

def trap(h):
    l,r=0,len(h)-1; lm=rm=ans=0
    while l<r:
        if h[l]<h[r]:
            lm=max(lm,h[l]); ans+=lm-h[l]; l+=1
        else:
            rm=max(rm,h[r]); ans+=rm-h[r]; r-=1
    return ans
